fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }

    // Check divisors from 2 up to sqrt(n) (optimization)
    let limit = (n as f64).sqrt() as i8 + 1;
    for k in 2..=limit {
        if n % k == 0 {
            return false;
        }
    }
    true
}